import type { GeospatialCamera } from "@babylonjs/lite";

export function tiltGlobeCamera(camera: GeospatialCamera, pitch: number): void {
  const current = { yaw: camera.yaw, radius: camera.radius, center: camera.center };
  const previousLimits = camera.limits;
  const permissiveLimits = {
    ...previousLimits,
    pitchMin: Math.min(previousLimits.pitchMin, pitch),
    pitchMax: Math.max(previousLimits.pitchMax, pitch),
    pitchDisabledRadiusScale: null,
  };
  camera.limits = permissiveLimits;
  camera._setOrientation(current.yaw, pitch, current.radius, current.center);
  camera.limits = previousLimits;
}
```
